import re

from fastapi import Header, HTTPException

from .database import get_db

SESSION_HEADER = "X-Session-ID"
_SESSION_RE = re.compile(r"^[A-Za-z0-9_-]{16,64}$")


def get_session_id(x_session_id: str | None = Header(default=None, alias=SESSION_HEADER)) -> str:
    """Anonymous per-visitor session id generated by the frontend (localStorage).
    It is not authentication; it only scopes data so demo visitors don't see
    each other's tasks."""
    if not x_session_id or not _SESSION_RE.match(x_session_id):
        raise HTTPException(
            status_code=400,
            detail=f"Missing or invalid {SESSION_HEADER} header (16-64 chars of [A-Za-z0-9_-]).",
        )
    return x_session_id


__all__ = ["get_db", "get_session_id", "SESSION_HEADER"]
